param([string]$Output='artifacts/sprint10-final-reconciliation.json',[int]$TimeoutSeconds=240,[string]$AgentData='artifacts/sprint5-windows-20260807063045')
$ErrorActionPreference='Stop';Set-Location(Resolve-Path(Join-Path $PSScriptRoot '..\..'))
function Sql([string]$q){docker exec deployment-postgres-1 psql -U platform -d platform -Atc $q}
function Os([string]$a){[long]((docker exec deployment-opensearch-1 curl -sf "http://localhost:9200/$a/_count"|ConvertFrom-Json).count)}
$domains=@('process','file','registry','network','dns','module','persistence','identity');$aliases=@('platform-processes','platform-files','platform-registry-events','platform-network-events','platform-dns-events','platform-module-events','platform-persistence-events','platform-identity-events');$queues=$domains
$deadline=[DateTimeOffset]::UtcNow.AddSeconds($TimeoutSeconds);do{Start-Sleep -Seconds 5;$v=(Sql "select (select count(*) from platform.process_entities)||'|'||(select count(*) from platform.file_entities)||'|'||(select count(*) from platform.registry_events)||'|'||(select count(*) from platform.network_events)||'|'||(select count(*) from platform.dns_events)||'|'||(select count(*) from platform.module_events)||'|'||(select count(*) from platform.persistence_events)||'|'||(select count(*) from platform.identity_events)||'|'||(select count(*) from platform.outbox where published_at is null and failed_at is null)||'|'||(select count(*) from platform.outbox where failed_at is not null);").Trim().Split('|')|%{[long]$_};$s=for($i=0;$i-lt$aliases.Count;$i++){Os $aliases[$i]};$q=[ordered]@{};foreach($name in $queues){$q[$name]=@(Get-ChildItem (Join-Path $AgentData "$name-queue") -File -Filter '*.json' -ErrorAction SilentlyContinue).Count};$js=docker exec deployment-nats-1 wget -qO- 'http://localhost:8222/jsz?streams=true&consumers=true'|ConvertFrom-Json;$c=@($js.account_details.stream_detail.consumer_detail);$pending=[long](($c|Measure-Object num_pending -Sum).Sum);$ack=[long](($c|Measure-Object num_ack_pending -Sum).Sum);$exact=$true;for($i=0;$i-lt$domains.Count;$i++){if($v[$i]-ne$s[$i]){$exact=$false}};$drained=@($q.Values|?{$_-ne0}).Count-eq0-and$v[8]-eq0-and$v[9]-eq0-and$pending-eq0-and$ack-eq0}while((-not($exact-and$drained))-and[DateTimeOffset]::UtcNow-lt$deadline)
$pg=[ordered]@{};$os=[ordered]@{};$diff=[ordered]@{};for($i=0;$i-lt$domains.Count;$i++){$pg[$domains[$i]]=$v[$i];$os[$domains[$i]]=$s[$i];$diff[$domains[$i]]=$v[$i]-$s[$i]};$identity=(Sql "select count(*)||'|'||count(distinct event_id)||'|'||(count(*)-count(distinct event_id))||'|'||coalesce(min(sequence),0)||'|'||coalesce(max(sequence),0) from platform.identity_events;").Split('|');$report=[ordered]@{schema='platform.sprint10.final-reconciliation.v1';capturedAt=[DateTimeOffset]::UtcNow.ToString('o');postgres=$pg;openSearch=$os;differences=$diff;identity=[ordered]@{rows=[long]$identity[0];uniqueEvents=[long]$identity[1];duplicates=[long]$identity[2];minimumSequence=[long]$identity[3];maximumSequence=[long]$identity[4]};queues=$q;identityQuarantine=@(Get-ChildItem (Join-Path $AgentData 'identity-queue\quarantine') -File -Filter '*.json' -ErrorAction SilentlyContinue).Count;outbox=[ordered]@{pending=$v[8];failed=$v[9]};nats=[ordered]@{pending=$pending;ackPending=$ack};passed=($exact-and$drained)};$report|ConvertTo-Json -Depth 8|Set-Content $Output -Encoding utf8;$report|ConvertTo-Json -Depth 8;if(!$report.passed){throw'Final reconciliation did not drain exactly.'}
